SELECT DATE_TRUNC('MONTH', customers.signup_date) AS signup_month, customers.country, MAX(subscriptions.monthly_fee) AS max_monthly_fee, SUM(CASE WHEN subscriptions.plan = 'standard' THEN 1 ELSE 0 END) AS standard_count FROM subscriptions FULL OUTER JOIN customers ON subscriptions.customer_id = customers.id WHERE customers.name NOT LIKE '%Henry%' GROUP BY DATE_TRUNC('MONTH', customers.signup_date), customers.country ORDER BY signup_month;
